/* sega_logo.h -- the authentic SEGA logo screen assets from Sonic 1 (REV00):
 * logo art + tilemaps, the palette-reveal animation, and the "SE-GA!" chant.
 * Extracted from the ROM (offsets in sega_intro_sonic1/README.md); data
 * generated by gen_sega_logo_kit.py -- do not hand-edit.
 *
 * Minimal use (SGDK, H40, right after VDP_init):
 *
 *   sega_logo_draw(TILE_USER_INDEX);            // tiles -> VRAM, both planes
 *   sega_palcycle_reset();                      // all-white CRAM mirror
 *   VDP_setBackgroundColor(0);
 *   PAL_setColors(0, sega_logo_cram, 64, CPU);  // screen all white
 *   SND_PCM_loadDriver(TRUE);
 *   while (sega_palcycle_step()) {              // the reveal: 75 frames
 *       VDP_waitVSync();
 *       PAL_setColors(0, sega_logo_cram, 64, CPU);
 *   }
 *   SND_PCM_startPlay(sega_chant_pcm, sizeof sega_chant_pcm,
 *                     SOUND_PCM_RATE_16000, SOUND_PAN_CENTER, FALSE);
 *   // chant is 0x6978 bytes @ 16 kHz = ~1.7 s; hold ~104 frames
 *
 * How it works (engine-neutral facts, usable outside SGDK):
 *  - plane A map = 40x28 white card with letter-shaped holes + TM (pal line
 *    0); plane B map = 24x8 solid color cells, one CRAM entry per letter
 *    column (pal lines 1-3), placed at tile (8,10), BEHIND plane A.
 *  - map words are raw VDP attributes with tile indices 0..122; add your
 *    VRAM base tile to bits 10-0, keep bits 15-11 (pri/pal/flip).
 *  - the animation never touches the tiles: a 6-color shimmer band sweeps
 *    CRAM entries 16-63 left->right, then 4 settle steps fade the letters
 *    white->blue (tables below; faithful port of PalCycle_Sega/$200A).
 *  - chant: 8-bit PCM, originally UNSIGNED at ~16.0 kHz (Z80 DAC loop
 *    timing); stored here SIGNED (^0x80) for SGDK's PCM driver, padded
 *    136 bytes to a 256 multiple, 256-aligned.
 *
 * The SEGA logotype + chant are SEGA's IP: personal homebrew only.
 */
#ifndef SEGA_LOGO_H
#define SEGA_LOGO_H

#include <genesis.h>

#define SEGA_LOGO_TILE_COUNT   123
#define SEGA_CHANT_PCM_LEN     27136     /* incl. 136 pad bytes */
#define SEGA_PALCYCLE_FRAMES   75       /* full reveal duration */

extern const u32 sega_logo_tiles[SEGA_LOGO_TILE_COUNT * 8];
extern const u16 sega_logo_map_a[28 * 40];   /* full screen card, BG_A */
extern const u16 sega_logo_map_b[8 * 24];    /* letter cells, BG_B at (8,10) */
extern const u8  sega_chant_pcm[SEGA_CHANT_PCM_LEN];

extern u16 sega_logo_cram[64];               /* palette mirror for the cycle */

/* Load tiles at vramBase and draw both planes (H40 layout, B behind A). */
void sega_logo_draw(u16 vramBase);

/* Reset cycle state + fill sega_logo_cram all-white ($0EEE). */
void sega_palcycle_reset(void);

/* Advance one frame; push sega_logo_cram to CRAM after each call.
 * Returns 0 when the reveal is complete. */
u16 sega_palcycle_step(void);

#endif
